// Uma busca por dia num ciclo de 10 dias com peso por região: 6 Fortaleza, 3 Região Metropolitana, 1 interior.
// Dentro de cada região, os termos se revezam. A posição (cursor) fica guardada por termo para não repetir perfis.
const sd = $getWorkflowStaticData('global');
const ciclo = ['F', 'M', 'F', 'F', 'M', 'F', 'I', 'F', 'M', 'F'];
const termos = {
  F: ['síndico profissional Fortaleza', 'síndico condomínio Fortaleza', 'gestor condominial Fortaleza', 'síndica Fortaleza', 'síndico morador Fortaleza', 'administração condominial Fortaleza'],
  M: ['síndico Caucaia', 'síndico Eusébio', 'síndico Maracanaú', 'síndico Aquiraz', 'síndico Maranguape', 'síndico Pacatuba'],
  I: ['síndico Juazeiro do Norte', 'síndico Sobral', 'síndico Crato', 'síndico Iguatu'],
};
const dia = sd.dia || 0;
const slot = ciclo[dia % ciclo.length];
const pos = (sd.pos || {})[slot] || 0;
const query = termos[slot][pos % termos[slot].length];
const cursores = sd.cursores || {};
return { json: { simular: $json.simular === true, dia, slot, query, cursor: cursores[query] || '' } };

// Resposta de mentira (sem chamar o LinkedIn) para testar o resto do fluxo.
return { json: { items: [
  { type: 'PEOPLE', name: 'ZZ Teste Sindico Simulado', public_identifier: 'zz-teste-sindico-simulado', public_profile_url: 'https://www.linkedin.com/in/zz-teste-sindico-simulado', headline: 'Síndico profissional', location: 'Fortaleza, Ceará, Brasil' },
  { type: 'PEOPLE', name: 'ZZ Teste Sindica Caucaia', public_identifier: 'zz-teste-sindica-caucaia', public_profile_url: 'https://www.linkedin.com/in/zz-teste-sindica-caucaia', headline: 'Síndica do condomínio', location: 'Caucaia, Ceará, Brasil' },
  { type: 'PEOPLE', name: 'ZZ Teste Fora Do Estado', public_identifier: 'zz-teste-fora', public_profile_url: 'https://www.linkedin.com/in/zz-teste-fora', headline: 'Síndico', location: 'São Paulo, Brasil' },
  { type: 'PEOPLE', name: 'ZZ Teste Nao E Sindico', public_identifier: 'zz-teste-nao-sindico', public_profile_url: 'https://www.linkedin.com/in/zz-teste-nao-sindico', headline: 'Crédito e Cobrança | Contabilidade', location: 'Fortaleza, Ceará, Brasil' },
  { type: 'PEOPLE', name: 'ZZ Teste Advogado', public_identifier: 'zz-teste-advogado', public_profile_url: 'https://www.linkedin.com/in/zz-teste-advogado', headline: 'Advocacia condominial', location: 'Fortaleza, Ceará, Brasil' }
], cursor: 'cursor-simulado' } };

// Fica só com quem é do Ceará E tem síndico/condomínio no cargo. Exclui advogados e corretores. Não envia nada para ninguém.
// A região (Fortaleza / metropolitana / interior) é calculada no banco a partir da localização gravada em origem_detalhe.
const ctx = $('Escolhe a busca do dia').item.json;
const itens = Array.isArray($json.items) ? $json.items : [];
const norm = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase();
const cidadesCE = /FORTALEZA|CAUCAIA|MARACANAU|MARANGUAPE|PACATUBA|AQUIRAZ|EUSEBIO|ITAITINGA|GUAIUBA|PACAJUS|HORIZONTE|CHOROZINHO|SAO GONCALO DO AMARANTE|PINDORETAMA|CASCAVEL|PARACURU|PARAIPABA|TRAIRI|JUAZEIRO DO NORTE|SOBRAL|CRATO|IGUATU|BARBALHA|ITAPIPOCA|QUIXADA|RUSSAS|ARACATI|CANINDE|CEARA/;
const temPerfilDeSindico = /s[ií]ndic|condom[ií]n|gest[aã]o predial|administra[cç][aã]o predial/i;
const naoEhAlvo = /advoga|advocacia|jur[ií]dic|direito|corretor|imobili[aá]ri/i;
const candidatos = [];
let fora = 0, irrelevantes = 0;
for (const p of itens) {
  if (p.type && String(p.type).toUpperCase() !== 'PEOPLE') continue;
  const loc = String(p.location || '');
  if (!cidadesCE.test(norm(loc))) { fora++; continue; }
  const head = String(p.headline || '');
  if (!temPerfilDeSindico.test(head) || naoEhAlvo.test(head)) { irrelevantes++; continue; }
  const url = p.public_profile_url || (p.public_identifier ? 'https://www.linkedin.com/in/' + p.public_identifier : '');
  if (!url || !p.name) continue;
  candidatos.push({ nome: String(p.name).trim(), linkedin_url: url, headline: head.trim(), location: loc });
}
return { json: { query: ctx.query, slot: ctx.slot, dia: ctx.dia, simular: ctx.simular, cursor_novo: $json.cursor || '', encontrados: itens.length, fora_do_ceara: fora, irrelevantes, candidatos } };

// Só avança a página da busca quando todos os candidatos novos couberam no limite de 5 do dia.
// Se bateu o limite, a mesma página é relida na próxima vez desse termo (quem já entrou é ignorado) e ninguém se perde.
const f = $('Filtra Ceará e separa candidatos').first().json;
const gravados = $input.all().filter(i => i.json && i.json.r).length;
const avancou = gravados < 5;
if (!f.simular) {
  const sd = $getWorkflowStaticData('global');
  sd.cursores = sd.cursores || {};
  if (avancou) sd.cursores[f.query] = f.cursor_novo;
  sd.dia = (f.dia || 0) + 1;
  sd.pos = sd.pos || {};
  sd.pos[f.slot] = (sd.pos[f.slot] || 0) + 1;
}
const regiao = { F: 'Fortaleza', M: 'Região Metropolitana', I: 'Interior' }[f.slot];
return [{ json: { busca: f.query, regiao_da_busca: regiao, encontrados: f.encontrados, fora_do_ceara: f.fora_do_ceara, irrelevantes: f.irrelevantes, candidatos: f.candidatos.length, gravados, pagina_avancou: avancou, simulado: f.simular } }];
